  beneficiaryManualMintTokensEvents: manualMintTokensEvents(
    where: { AND: [{ beneficiary: $address }, { from_not: $address }, { version: 6 }] }
    orderBy: "timestamp"
    orderDirection: "desc"
    limit: $limit
    offset: $offset
  ) {
    totalCount
